'use strict';

// MODULES //

var createHash = require( 'crypto' ).createHash;
var isString = require( '@stdlib/assert/is-string' ).isPrimitive;
var isNumber = require( '@stdlib/assert/is-number' ).isPrimitive;
var isBoolean = require( '@stdlib/assert/is-boolean' ).isPrimitive;
var isBuffer = require( '@stdlib/assert/is-buffer' );
var isObject = require( '@stdlib/assert/is-object' );
var isNull = require( '@stdlib/assert/is-null' );
var isArray = require( '@stdlib/assert/is-array' );
var objectKeys = require( '@stdlib/utils/keys' );
var join = require( '@stdlib/array/base/join' );
var format = require( '@stdlib/string/format' );


// FUNCTIONS //

/**
* Serializes a value using sorted object keys and ordered arrays.
*
* @private
* @param {*} value - value to serialize
* @returns {(string|void)} serialized value
*/
function serialize( value ) {
	var keys;
	var out;
	var tmp;
	var i;

	// Use JSON scalar spellings so that hashes do not depend on implicit string coercion or runtime-specific object formatting...
	if ( isNull( value ) ) {
		return 'null';
	}
	if ( isNumber( value ) || isBoolean( value ) || isString( value ) ) {
		return JSON.stringify( value );
	}
	if ( isArray( value ) ) {
		// Array order is semantic. Match JSON behavior by serializing unsupported array members as null rather than omitting their positions...
		out = [];
		for ( i = 0; i < value.length; i++ ) {
			tmp = serialize( value[ i ] );
			out.push( ( tmp === void 0 ) ? 'null' : tmp );
		}
		return format( '[%s]', join( out, ',' ) );
	}
	if ( isObject( value ) ) {
		// Sort object keys to make hashes independent of property insertion order and omit unsupported object values to match `JSON.stringify` semantics...
		keys = objectKeys( value ).sort();
		out = [];
		for ( i = 0; i < keys.length; i++ ) {
			tmp = serialize( value[ keys[ i ] ] );
			if ( tmp !== void 0 ) {
				out.push( format( '%s:%s', JSON.stringify( keys[ i ] ), tmp ) );
			}
		}
		return format( '{%s}', join( out, ',' ) );
	}
}


// MAIN //

/**
* Computes a SHA-256 digest for a value.
*
* @private
* @param {*} value - value to hash
* @returns {string} digest
*/
function hash( value ) {
	var input;

	// Strings and Buffers are hashed as their exact bytes. Structured values use the canonical serializer above to produce deterministic semantic hashes...
	if ( isString( value ) || isBuffer( value ) ) {
		input = value;
	} else {
		input = serialize( value );
	}
	return format( 'sha256:%s', createHash( 'sha256' ).update( input ).digest( 'hex' ) );
}


// EXPORTS //

hash.serialize = serialize;
module.exports = hash;
